package com.cosmetic.shopbackend.dashboard;

import java.sql.Date;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.BadSqlGrammarException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;

/** Queries pre-aggregated DW marts; it never exposes an individual customer's data. */
@Service
public class DashboardMartService {
  private static final ZoneId KST = ZoneId.of("Asia/Seoul");
  private static final Set<String> ACTOR_TYPES = Set.of("all", "web", "synthetic");
  private static final Pattern DW_TABLE = Pattern.compile("dw\\.([a-z_]+)");
  private final JdbcTemplate shopJdbc;
  private final DashboardMartJdbcProvider martJdbc;

  public DashboardMartService(JdbcTemplate shopJdbc, DashboardMartJdbcProvider martJdbc) { this.shopJdbc = shopJdbc; this.martJdbc = martJdbc; }

  public Map<String, Object> commerceSummary(String sellerId, String brandId) {
    owns(sellerId, brandId);
    return shopJdbc.queryForMap("select count(distinct oi.order_id) orders,coalesce(sum(oi.line_amount),0) revenue,(select count(*) from review r join order_item x on x.order_item_id=r.order_item_id where x.brand_id=?) reviews,(select count(*) from feedback f join order_item x on x.order_item_id=f.order_item_id where x.brand_id=? and f.status='VISIBLE') feedbacks from order_item oi join shop_order o on o.order_id=oi.order_id where oi.brand_id=? and o.status='PAID'", brandId, brandId, brandId);
  }

  public Map<String, Object> overview(String seller, String brand, String from, String to, String actor) {
    Query q = request(seller, brand, from, to, actor);
    Map<String,Object> current = one("select coalesce(sum(impression_sessions),0) impression_sessions,coalesce(sum(product_view_sessions),0) product_view_sessions,coalesce(sum(information_view_sessions),0) information_view_sessions,coalesce(sum(add_to_cart_sessions),0) add_to_cart_sessions,coalesce(sum(detail_view_sessions),0) detail_view_sessions,coalesce(sum(unique_user_count),0) unique_user_count,coalesce(sum(product_count_viewed),0) product_count_viewed," + ratio("detail_view_sessions","impression_sessions","detail_entry_rate") + "," + ratio("information_view_sessions","product_view_sessions","information_view_rate") + "," + ratio("add_to_cart_sessions","detail_view_sessions","view_to_cart_rate") + ",min(mart_processed_at) mart_processed_at from dw.brand_daily_kpi where " + q.where("event_date_kst"), q.args());
    current.putAll(one("select coalesce(sum(product_view_count),0) product_view_count,coalesce(sum(add_to_cart_count),0) add_to_cart_count,coalesce(sum(remove_from_cart_count),0) remove_from_cart_count,coalesce(sum(add_to_cart_sessions),0) add_to_cart_sessions_by_product,coalesce(sum(remove_from_cart_sessions),0) remove_from_cart_sessions," + ratio("remove_from_cart_sessions","add_to_cart_sessions","removal_rate") + " from dw.product_daily_kpi where " + q.where("event_date_kst"),q.args()));
    Query previous = q.previous();
    Map<String,Object> prev = one("select coalesce(sum(impression_sessions),0) impression_sessions,coalesce(sum(product_view_sessions),0) product_view_sessions,coalesce(sum(information_view_sessions),0) information_view_sessions,coalesce(sum(add_to_cart_sessions),0) add_to_cart_sessions,coalesce(sum(detail_view_sessions),0) detail_view_sessions,coalesce(sum(unique_user_count),0) unique_user_count,coalesce(sum(product_count_viewed),0) product_count_viewed," + ratio("detail_view_sessions","impression_sessions","detail_entry_rate") + "," + ratio("information_view_sessions","product_view_sessions","information_view_rate") + "," + ratio("add_to_cart_sessions","detail_view_sessions","view_to_cart_rate") + " from dw.brand_daily_kpi where " + previous.where("event_date_kst"),previous.args());
    prev.putAll(one("select coalesce(sum(product_view_count),0) product_view_count,coalesce(sum(add_to_cart_count),0) add_to_cart_count,coalesce(sum(remove_from_cart_count),0) remove_from_cart_count,coalesce(sum(add_to_cart_sessions),0) add_to_cart_sessions_by_product,coalesce(sum(remove_from_cart_sessions),0) remove_from_cart_sessions," + ratio("remove_from_cart_sessions","add_to_cart_sessions","removal_rate") + " from dw.product_daily_kpi where " + previous.where("event_date_kst"),previous.args()));
    List<Map<String,Object>> daily = many("select event_date_kst,coalesce(sum(product_view_sessions),0) product_view_sessions,coalesce(sum(add_to_cart_sessions),0) add_to_cart_sessions,coalesce(sum(unique_user_count),0) unique_user_count from dw.brand_daily_kpi where " + q.where("event_date_kst") + " group by event_date_kst order by event_date_kst",q.args());
    Map<String,Object> funnel = one("select coalesce(sum(impression_sessions),0) impression_sessions,coalesce(sum(click_sessions),0) click_sessions,coalesce(sum(quick_look_sessions),0) quick_look_sessions,coalesce(sum(quick_look_cart_sessions),0) quick_look_cart_sessions,coalesce(sum(product_view_sessions),0) product_view_sessions,coalesce(sum(detail_view_sessions),0) detail_view_sessions,coalesce(sum(information_view_sessions),0) information_view_sessions,coalesce(sum(add_to_cart_sessions),0) add_to_cart_sessions,coalesce(sum(checkout_sessions),0) checkout_sessions,coalesce(sum(purchase_sessions),0) purchase_sessions from dw.funnel_daily_kpi where " + q.where("funnel_date_kst"),q.args());
    return envelope(q,List.of("brand_daily_kpi","product_daily_kpi","funnel_daily_kpi"),exists("brand_daily_kpi",q,"event_date_kst"),current.get("mart_processed_at"),Map.of("current",current,"previous",prev,"daily",daily,"funnel",funnel));
  }

  public Map<String, Object> products(String seller, String brand, String from, String to, String actor) {
    Query q=request(seller,brand,from,to,actor);
    List<Map<String,Object>> products=many("select product_id,coalesce(sum(product_impression_count),0) product_impression_count,coalesce(sum(product_click_count),0) product_click_count,coalesce(sum(quick_look_count),0) quick_look_count,coalesce(sum(product_view_count),0) product_view_count,coalesce(sum(add_to_cart_count),0) add_to_cart_count,coalesce(sum(remove_from_cart_count),0) remove_from_cart_count,coalesce(sum(variant_select_count),0) variant_select_count,coalesce(sum(quick_look_close_open_detail_count),0) quick_look_close_open_detail_count,coalesce(sum(quick_look_sessions),0) quick_look_sessions,coalesce(sum(product_view_sessions),0) product_view_sessions,coalesce(sum(detail_view_sessions),0) detail_view_sessions,coalesce(sum(add_to_cart_sessions),0) add_to_cart_sessions,coalesce(sum(remove_from_cart_sessions),0) remove_from_cart_sessions,coalesce(sum(session_count),0) session_count,coalesce(sum(unique_user_count),0) unique_user_count,coalesce(sum(product_interest_score),0) product_interest_score,"+ratio("product_click_count","product_impression_count","product_ctr")+","+ratio("product_view_sessions","product_click_count","detail_entry_rate")+","+ratio("add_to_cart_sessions","detail_view_sessions","add_to_cart_rate")+",min(mart_processed_at) mart_processed_at from dw.product_daily_kpi where "+q.where("event_date_kst")+" group by product_id",q.args());
    Map<String,Map<String,Object>> funnels=indexed(many("select product_id,coalesce(sum(impression_sessions),0) impression_sessions,coalesce(sum(click_sessions),0) click_sessions,coalesce(sum(quick_look_sessions),0) quick_look_sessions,coalesce(sum(quick_look_cart_sessions),0) quick_look_cart_sessions,coalesce(sum(product_view_sessions),0) product_view_sessions,coalesce(sum(detail_view_sessions),0) detail_view_sessions,coalesce(sum(information_view_sessions),0) information_view_sessions,coalesce(sum(add_to_cart_sessions),0) add_to_cart_sessions from dw.funnel_daily_kpi where "+q.where("funnel_date_kst")+" group by product_id",q.args()));
    Map<String,Map<String,Object>> exits=indexed(many("select e.product_id,e.last_content_kind exit_content_kind_top,e.exit_sessions from dw.product_exit_daily e join (select product_id,max(exit_sessions) max_exits from dw.product_exit_daily where "+q.where("event_date_kst")+" group by product_id) top on top.product_id=e.product_id and top.max_exits=e.exit_sessions where "+q.where("event_date_kst"),concat(q.args(),q.args())));
    for(Map<String,Object> p:products){ p.put("funnel",funnels.get(String.valueOf(p.get("product_id")))); Map<String,Object> e=exits.get(String.valueOf(p.get("product_id"))); Map<String,Object> d=new LinkedHashMap<>(); d.put("exit_content_kind_top",e==null?null:e.get("exit_content_kind_top")); d.put("exit_sessions",e==null?0:e.get("exit_sessions")); d.put("variant_select_per_session",divide(p.get("variant_select_count"),p.get("detail_view_sessions"))); d.put("quick_look_open_detail_rate",divide(p.get("quick_look_close_open_detail_count"),p.get("quick_look_sessions"))); p.put("diagnostics",d); }
    return envelope(q,List.of("product_daily_kpi","funnel_daily_kpi","product_exit_daily"),!products.isEmpty(),processed(products),Map.of("products",products));
  }

  public Map<String,Object> content(String seller,String brand,String from,String to,String actor){
    Query q=request(seller,brand,from,to,actor);
    List<Map<String,Object>> rows=many("select content_kind,coalesce(sum(section_view_count),0) section_view_count,coalesce(sum(section_view_sessions),0) section_view_sessions,coalesce(sum(dwell_ms_sum),0) dwell_ms_sum,coalesce(sum(accordion_expand_count),0) accordion_expand_count,coalesce(sum(text_selection_count),0) text_selection_count,coalesce(sum(text_copy_count),0) text_copy_count,coalesce(sum(matched_ingredient_count),0) matched_ingredient_count,coalesce(sum(product_view_sessions),0) product_view_sessions,"+ratio("dwell_ms_sum","section_view_sessions","avg_dwell_ms_per_session")+","+ratio("section_view_sessions","product_view_sessions","view_rate")+",min(mart_processed_at) mart_processed_at from dw.content_daily_kpi where "+q.where("event_date_kst")+" group by content_kind",q.args());
    Map<String,Map<String,Object>> conversions=indexed(many("select content_kind,coalesce(sum(viewed_sessions),0) viewed_sessions,coalesce(sum(viewed_cart_sessions),0) viewed_cart_sessions from dw.content_conversion_daily where "+q.where("event_date_kst")+" group by content_kind",q.args()),"content_kind"); Map<String,Object> base=brandBase(q);
    for(Map<String,Object> row:rows){Map<String,Object> c=conversions.get(String.valueOf(row.get("content_kind"))); if(c==null){row.put("conversion",null);}else{double viewed=number(c.get("viewed_sessions")); double cartRate=number(c.get("viewed_cart_sessions"))/Math.max(viewed,1); Map<String,Object> out=new LinkedHashMap<>(c); out.put("cart_lift",number(base.get("view_to_cart_rate"))==0?null:cartRate/number(base.get("view_to_cart_rate"))); row.put("conversion",out);}}
    List<Map<String,Object>> behaviors=many("select event_name event,coalesce(sum(done_sessions),0) done_sessions,"+ratio("done_cart_sessions","done_sessions","cart_rate_with")+","+ratio("not_done_cart_sessions","not_done_sessions","cart_rate_without")+" from dw.behavior_conversion_daily where "+q.where("event_date_kst")+" group by event_name",q.args());
    return envelope(q,List.of("content_daily_kpi","content_conversion_daily","behavior_conversion_daily","brand_daily_kpi"),!rows.isEmpty(),processed(rows),Map.of("by_content_kind",rows,"brand",base,"behaviors",behaviors));
  }

  public Map<String,Object> segments(String seller,String brand,String from,String to,String actor){Query q=request(seller,brand,from,to,actor); List<Map<String,Object>> rows=many("select segment_type,segment_value,coalesce(sum(segment_user_count),0) segment_user_count,coalesce(sum(session_count),0) session_count,coalesce(sum(product_view_sessions),0) product_view_sessions,coalesce(sum(detail_view_sessions),0) detail_view_sessions,coalesce(sum(add_to_cart_sessions),0) add_to_cart_sessions,"+ratio("add_to_cart_sessions","detail_view_sessions","view_to_cart_rate")+",avg(avg_interest_score) avg_interest_score,min(mart_processed_at) mart_processed_at from dw.persona_segment_daily_kpi where "+q.where("event_date_kst")+" group by segment_type,segment_value",q.args()); List<Map<String,Object>> grid=rows.stream().filter(x->"skin_type_x_skin_tone".equals(x.get("segment_type"))).map(this::gridCell).filter(x->x!=null).toList(); List<Map<String,Object>> top=many("select skin_type,content_kind,coalesce(sum(dwell_ms_sum),0) dwell_ms_sum,"+ratio("sum(dwell_ms_sum)","sum(segment_dwell_ms_sum)","dwell_share")+" from dw.segment_content_daily where "+q.where("event_date_kst")+" group by skin_type,content_kind",q.args()); return envelope(q,List.of("persona_segment_daily_kpi","segment_content_daily"),!rows.isEmpty(),processed(rows),nullableBody("by_segment",rows,"grid",grid,"top_content",top,"same_skin_filter_rate",null));}

  public Map<String,Object> ingredients(String seller,String brand,String from,String to,String actor){Query q=request(seller,brand,from,to,actor); List<Map<String,Object>> rows=many("select ingredient_id,max(ingredient) ingredient,max(label_ko) label_ko,max(vocab_version) vocab_version,coalesce(sum(ingredient_interest_score),0) ingredient_interest_score,coalesce(sum(direct_match_score),0) direct_match_score,coalesce(sum(product_attributed_score),0) product_attributed_score,coalesce(sum(contributing_event_count),0) contributing_event_count,min(mart_processed_at) mart_processed_at from dw.ingredient_weekly_interest where "+q.whereNoBrand("interest_week_kst")+" group by ingredient_id",q.argsNoBrand()); double total=rows.stream().mapToDouble(x->number(x.get("ingredient_interest_score"))).sum(); for(Map<String,Object> row:rows)row.put("ingredient_interest_share",total==0?null:number(row.get("ingredient_interest_score"))/total); List<Object> weeks=many("select distinct interest_week_kst from dw.ingredient_weekly_interest where "+q.whereNoBrand("interest_week_kst")+" order by interest_week_kst",q.argsNoBrand()).stream().map(x->x.get("interest_week_kst")).toList(); return envelope(q,List.of("ingredient_weekly_interest"),!rows.isEmpty(),processed(rows),Map.of("weeks",weeks,"by_ingredient",rows));}

  public Map<String,Object> friction(String seller,String brand,String from,String to,String actor){Query q=request(seller,brand,from,to,actor); List<Map<String,Object>> locations=many("select section_id,event_name,coalesce(sum(event_count),0) event_count,coalesce(sum(friction_sessions),0) session_count,min(mart_processed_at) mart_processed_at from dw.friction_daily where "+q.where("event_date_kst")+" group by section_id,event_name",q.args()); Map<String,Object> counts=new LinkedHashMap<>(Map.of("rage_click",0,"dead_click",0,"scroll_backtrack",0)); for(Map<String,Object>x:many("select event_name,sum(event_count) event_count from dw.friction_daily where "+q.where("event_date_kst")+" group by event_name",q.args()))counts.put(String.valueOf(x.get("event_name")),x.get("event_count")); Map<String,Object> exit=one("select "+ratio("sum(quick_exit_sessions)","sum(detail_view_sessions)","quick_exit_rate")+" from dw.exit_daily where "+q.where("event_date_kst"),q.args()); List<Map<String,Object>> entry=many("select entry_source,sum(product_view_sessions) product_view_sessions,sum(detail_view_sessions) detail_view_sessions,sum(add_to_cart_sessions) add_to_cart_sessions,"+ratio("sum(add_to_cart_sessions)","sum(detail_view_sessions)","view_to_cart_rate")+" from dw.entry_source_daily where "+q.where("event_date_kst")+" group by entry_source",q.args()); List<Map<String,Object>> volumes=many("select event_name,sum(event_count) event_count from dw.event_daily where "+q.where("event_date_kst")+" group by event_name",q.args()); return envelope(q,List.of("friction_daily","exit_daily","entry_source_daily","event_daily"),!locations.isEmpty(),processed(locations),nullableBody("by_location",locations,"counts",counts,"quick_exit_rate",exit.get("quick_exit_rate"),"entry_source",entry,"event_volumes",volumes));}

  public Map<String,Object> purchase(String seller,String brand,String from,String to,String actor){Query q=request(seller,brand,from,to,actor); List<Map<String,Object>> brands=many("select * from dw.brand_repurchase_daily where "+q.where("snapshot_date_kst")+" order by snapshot_date_kst desc limit 1",q.args()); List<Map<String,Object>> products=many("select * from dw.product_repurchase_daily where "+q.where("snapshot_date_kst")+" and snapshot_date_kst=(select max(snapshot_date_kst) from dw.product_repurchase_daily where "+q.where("snapshot_date_kst")+")",concat(q.args(),q.args())); List<Map<String,Object>> reasons=many("select reason,sum(order_count) order_count,sum(primary_order_count) primary_order_count from dw.purchase_reason_daily where "+q.where("event_date_kst")+" group by reason",q.args()); double total=reasons.stream().mapToDouble(x->number(x.get("order_count"))).sum(); for(Map<String,Object>r:reasons)r.put("reason_share",total==0?null:number(r.get("order_count"))/total); return envelope(q,List.of("brand_repurchase_daily","product_repurchase_daily","purchase_reason_daily"),!brands.isEmpty()||!products.isEmpty()||!reasons.isEmpty(),processed(products),nullableBody("brand",brands.isEmpty()?null:brands.getFirst(),"products",products,"reasons",reasons));}

  private Query request(String seller,String brand,String from,String to,String actor){owns(seller,brand);return Query.parse(brand,from,to,actor);} private void owns(String seller,String brand){Integer count=shopJdbc.queryForObject("select count(*) from brand where brand_id=? and seller_account_id=?",Integer.class,brand,seller);if(count==null||count==0)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"brand access denied");}
  private Map<String,Object> one(String sql,Object...args){try{return new LinkedHashMap<>(martJdbc.jdbc().queryForMap(sql,args));}catch(BadSqlGrammarException e){throw unavailable(e);}} private List<Map<String,Object>> many(String sql,Object...args){try{return martJdbc.jdbc().queryForList(sql,args).stream().<Map<String,Object>>map(LinkedHashMap::new).toList();}catch(BadSqlGrammarException e){throw unavailable(e);}} private boolean exists(String table,Query q,String date){try{Integer n=martJdbc.jdbc().queryForObject("select count(*) from dw."+table+" where "+q.where(date),Integer.class,q.args());return n!=null&&n>0;}catch(BadSqlGrammarException e){throw unavailable(e);}} private DashboardMartUnavailableException unavailable(BadSqlGrammarException e){Matcher m=DW_TABLE.matcher(e.getSql());return new DashboardMartUnavailableException(m.find()?m.group(1):"unknown");} private static String ratio(String n,String d,String alias){String numerator=n.contains("(")?n:"sum("+n+")";String denominator=d.contains("(")?d:"sum("+d+")";return "case when "+denominator+"=0 then null else "+numerator+"/"+denominator+" end "+alias;} private static double number(Object v){return v instanceof Number n?n.doubleValue():0;} private static Double divide(Object n,Object d){return number(d)==0?null:number(n)/number(d);} private Map<String,Map<String,Object>> indexed(List<Map<String,Object>> rows){return indexed(rows,"product_id");} private Map<String,Map<String,Object>> indexed(List<Map<String,Object>> rows,String key){Map<String,Map<String,Object>>out=new LinkedHashMap<>();for(Map<String,Object>r:rows)out.put(String.valueOf(r.get(key)),r);return out;} private Object processed(List<Map<String,Object>>rows){return rows.stream().map(x->x.get("mart_processed_at")).filter(x->x!=null).findFirst().orElse(null);} private Map<String,Object> brandBase(Query q){return one("select sum(product_view_sessions) product_view_sessions,sum(detail_view_sessions) detail_view_sessions,sum(add_to_cart_sessions) add_to_cart_sessions,"+ratio("sum(add_to_cart_sessions)","sum(detail_view_sessions)","view_to_cart_rate")+" from dw.brand_daily_kpi where "+q.where("event_date_kst"),q.args());} private Map<String,Object> gridCell(Map<String,Object>r){String[]v=String.valueOf(r.get("segment_value")).split("\\|",2);if(v.length!=2)return null;Map<String,Object>x=new LinkedHashMap<>();x.put("skin_type",v[0]);x.put("skin_tone",v[1]);for(String k:List.of("product_view_sessions","detail_view_sessions","add_to_cart_sessions","view_to_cart_rate"))x.put(k,r.get(k));return x;} private Map<String,Object> nullableBody(Object...v){Map<String,Object>out=new LinkedHashMap<>();for(int i=0;i<v.length;i+=2)out.put((String)v[i],v[i+1]);return out;} private Object[] concat(Object[]a,Object[]b){Object[]out=new Object[a.length+b.length];System.arraycopy(a,0,out,0,a.length);System.arraycopy(b,0,out,a.length,b.length);return out;}
  private Map<String,Object> envelope(Query q,List<String>marts,boolean coverage,Object processed,Map<String,Object>body){Map<String,Object>source=new LinkedHashMap<>();source.put("marts",marts);source.put("mart_processed_at",processed);source.put("coverage",coverage?"full":"none");Map<String,Object>out=new LinkedHashMap<>();out.put("brand_id",q.brand);out.put("range",Map.of("from",q.from.toString(),"to",q.to.toString(),"days",q.days()));out.put("actor_type",q.actor);out.put("source",source);out.putAll(body);return out;}
  private record Query(String brand,LocalDate from,LocalDate to,String actor){static Query parse(String brand,String rawFrom,String rawTo,String rawActor){String actor=rawActor==null||rawActor.isBlank()?"all":rawActor;if(!ACTOR_TYPES.contains(actor))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"bad_actor_type");LocalDate end,start;try{end=rawTo==null||rawTo.isBlank()?LocalDate.now(KST).minusDays(1):LocalDate.parse(rawTo);start=rawFrom==null||rawFrom.isBlank()?end.minusDays(13):LocalDate.parse(rawFrom);}catch(RuntimeException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"bad_range");}if(start.isAfter(end))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"bad_range");if(end.toEpochDay()-start.toEpochDay()+1>92)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"range_too_long");return new Query(brand,start,end,actor);}String where(String date){return "brand_id=? and "+date+" between ? and ?"+clause();}String whereNoBrand(String date){return date+" between ? and ?"+clause();}Object[]args(){return actor.equals("all")?new Object[]{brand,Date.valueOf(from),Date.valueOf(to)}:new Object[]{brand,Date.valueOf(from),Date.valueOf(to),actor};}Object[]argsNoBrand(){return actor.equals("all")?new Object[]{Date.valueOf(from),Date.valueOf(to)}:new Object[]{Date.valueOf(from),Date.valueOf(to),actor};}String clause(){return actor.equals("all")?"":" and actor_type=?";}int days(){return(int)(to.toEpochDay()-from.toEpochDay()+1);}Query previous(){return new Query(brand,from.minusDays(days()),from.minusDays(1),actor);}}
}
